from pathlib import Path
import json,csv,collections
OUT=Path(__file__).resolve().parent
ROOT=OUT.parents[1]
def save(name,rows):
 (OUT/(name+'.json')).write_text(json.dumps(rows,indent=2,ensure_ascii=False))
 with (OUT/(name+'.csv')).open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader()
  for r in rows:w.writerow({k:'; '.join(map(str,v)) if isinstance(v,list) else v for k,v in r.items()})
sources=json.loads((OUT/'source_register.json').read_text())
