for s in sources:
 s['document_date_or_cohort'],s['locator']=extra[s['source_id']]
 s['retrieval_state']='direct_readable_primary' if s['direct_content_verified'] else ('primary_search_retrieved_only' if s['source_id'] in refs else 'not_content_verified')
